import { expandWideMoves } from '@cubeforge/math-core';
import type { AlgorithmCase, Algorithm } from '../schema';

export const F2L_BASIC_SUBSET_ID = '00000000-0000-4000-9000-000000000003';
export const F2L_ADVANCED_SUBSET_ID = '00000000-0000-4000-9000-000000000004';

/** Count moves in HTM/QTM/STM. Handles wide moves (Rw, Uw, etc.) and slice moves. */
function computeMetricFromString(movesStr: string, metric: 'htm' | 'qtm' | 'stm'): number {
  const tokens = movesStr.trim().split(/\s+/).filter(Boolean);
  let count = 0;
  for (let t of tokens) {
    // Remove grouping parentheses and normalize prime notation
    t = t.replace(/[()]/g, '').replace(/['′]2/g, '2').replace(/2['′]/g, '2');
    // Extract base face: handles R, Rw, r, R2, Rw2, etc.
    const baseMatch = t.match(/^([RLUDFB]w?|[rludfbMES])(2|'|′)?$/);
    if (!baseMatch) continue; // skip invalid tokens silently
    const base = baseMatch[1];
    const isHalfTurn = baseMatch[2] === '2';
    // Full-cube rotations (x, y, z) are ignored in all metrics
    const isRotation = base === 'x' || base === 'y' || base === 'z';
    if (isRotation) continue;
    // Slice moves (M, E, S) count in all metrics
    if (metric === 'stm') { count++; continue; }
    if (metric === 'htm') { count++; continue; }
    // QTM: half turns = 2, quarter turns = 1
    count += isHalfTurn ? 2 : 1;
  }
  return count;
}

function makeAlg(
  id: string, caseId: string, movesStr: string, isDefault = true,
  difficulty: 'beginner' | 'intermediate' | 'advanced' = 'intermediate',
  notes?: string,
): Algorithm {
  const moves = expandWideMoves(movesStr);
  return {
    id, caseId, moves,
    moveCount: {
      htm: computeMetricFromString(movesStr, 'htm'),
      qtm: computeMetricFromString(movesStr, 'qtm'),
      stm: computeMetricFromString(movesStr, 'stm'),
    },
    isDefault, source: 'SpeedCubeDB', difficulty, triggers: [], notes,
    isMirror: false, isInverse: false,
  };
}

export interface F2LCaseData { caseDef: AlgorithmCase; algorithms: Algorithm[] }

// ─── Basic F2L Cases (41 Cases from SpeedCubeDB) ────────────────────────

function bCase(id: string, num: string, cat: string, setup: string, ...algs: [string, string][]): F2LCaseData {
  return {
    caseDef: {
      id, subsetId: F2L_BASIC_SUBSET_ID, caseNumber: num, name: num,
      recognitionPatterns: [], setupScramble: setup, diagramType: '3d-isometric',
      probability: '1/41', difficulty: 'beginner', category: cat,
      tags: ['f2l', 'basic'], puzzleType: '3x3x3',
    },
    algorithms: algs.map(([moves, slot], i) =>
      makeAlg(`${id}-alg${i}`, id, moves, i === 0, 'beginner', `Slot: ${slot}`),
    ),
  };
}

